import{_ as n,o as s,c as t,am as e}from"./chunks/framework._FJXuPhs.js";const h=JSON.parse('{"title":"Maven工具_基础使用","description":"","frontmatter":{"title":"Maven工具_基础使用","excerpt":"主要的陈述一下如何下载安装，以及IDEA中的基础配置内容（基础使用篇）","date":"2023-11-24 21:18:04","updated":"2023-11-24 21:18:04"},"headers":[],"relativePath":"环境部署&工具/部署&工具 构建工具/Maven 进阶内容/Maven工具_基础使用.md","filePath":"环境部署&工具/部署&工具 构建工具/Maven 进阶内容/Maven工具_基础使用.md","lastUpdated":null}'),p={name:"环境部署&工具/部署&工具 构建工具/Maven 进阶内容/Maven工具_基础使用.md"};function l(i,a,r,o,c,g){return s(),t("div",null,[...a[0]||(a[0]=[e(`<h3 id="_1、maven-下载与安装" tabindex="-1">1、Maven 下载与安装 <a class="header-anchor" href="#_1、maven-下载与安装" aria-label="Permalink to &quot;1、Maven 下载与安装&quot;">​</a></h3><p>官网： <a href="https://maven.apache.org/" target="_blank" rel="noreferrer">https://maven.apache.org/</a></p><p>/Library/Java/apache-maven-3.9.7/repository</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/20241005221007.png" alt="image.png"></p><h3 id="_2、maven配置文件修改" tabindex="-1">2、Maven配置文件修改 <a class="header-anchor" href="#_2、maven配置文件修改" aria-label="Permalink to &quot;2、Maven配置文件修改&quot;">​</a></h3><blockquote><p>maven 配置文件内容</p></blockquote><p>设置本地仓库路径</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!--设置本地仓库路径--&gt;</span></span>
<span class="line"><span>&lt;localRepository&gt;D:\\java\\maven\\localRepository&lt;/localRepository&gt;</span></span></code></pre></div><p>配置阿里云私服（或换成自己公司搭建的私服）</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!-- 在mirrors标签里添加mirror标签，并指定阿里云私服下载依赖会快点 --&gt;</span></span>
<span class="line"><span>&lt;mirror&gt;</span></span>
<span class="line"><span>  &lt;id&gt;alimaven&lt;/id&gt;</span></span>
<span class="line"><span>  &lt;name&gt;aliyun maven&lt;/name&gt;</span></span>
<span class="line"><span>  &lt;url&gt;http://maven.aliyun.com/nexus/content/groups/public/&lt;/url&gt;</span></span>
<span class="line"><span>  &lt;mirrorOf&gt;central&lt;/mirrorOf&gt;</span></span>
<span class="line"><span>&lt;/mirror&gt;</span></span></code></pre></div><p>配置 maven 默认jdk版本</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!-- 在已有的profiles标签中添加profile标签，限定maven项目默认的jdk版本 --&gt;</span></span>
<span class="line"><span>&lt;profile&gt;    </span></span>
<span class="line"><span>    &lt;id&gt;myjdk&lt;/id&gt;    </span></span>
<span class="line"><span>    &lt;activation&gt;    </span></span>
<span class="line"><span>        &lt;activeByDefault&gt;true&lt;/activeByDefault&gt;    </span></span>
<span class="line"><span>        &lt;jdk&gt;1.8&lt;/jdk&gt;    </span></span>
<span class="line"><span>    &lt;/activation&gt;    </span></span>
<span class="line"><span>    &lt;properties&gt;    </span></span>
<span class="line"><span>        &lt;maven.compiler.source&gt;1.8&lt;/maven.compiler.source&gt;    </span></span>
<span class="line"><span>        &lt;maven.compiler.target&gt;1.8&lt;/maven.compiler.target&gt;</span></span>
<span class="line"><span>        &lt;maven.compiler.compilerVersion&gt;1.8&lt;/maven.compiler.compilerVersion&gt; </span></span>
<span class="line"><span>    &lt;/properties&gt;    </span></span>
<span class="line"><span>&lt;/profile&gt;</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>&lt;!-- 让增加的 profile生效 --&gt;</span></span>
<span class="line"><span>&lt;activeProfiles&gt;</span></span>
<span class="line"><span>  &lt;activeProfile&gt;myjdk&lt;/activeProfile&gt;</span></span>
<span class="line"><span>&lt;/activeProfiles&gt;</span></span></code></pre></div><p>配置华为云</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  &lt;mirror&gt;</span></span>
<span class="line"><span>	&lt;id&gt;huaweicloud&lt;/id&gt;</span></span>
<span class="line"><span>	&lt;url&gt;https://repo.huaweicloud.com/repository/maven/&lt;/url&gt;</span></span>
<span class="line"><span>	&lt;mirrorOf&gt;central&lt;/mirrorOf&gt;</span></span>
<span class="line"><span>  &lt;/mirror&gt;</span></span></code></pre></div><p>阿里云: <a href="https://developer.aliyun.com/mvn/guide" target="_blank" rel="noreferrer">https://developer.aliyun.com/mvn/guide</a></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;mirror&gt;</span></span>
<span class="line"><span>  &lt;id&gt;aliyunmaven&lt;/id&gt;</span></span>
<span class="line"><span>  &lt;mirrorOf&gt;*&lt;/mirrorOf&gt;</span></span>
<span class="line"><span>  &lt;name&gt;阿里云公共仓库&lt;/name&gt;</span></span>
<span class="line"><span>  &lt;url&gt;https://maven.aliyun.com/repository/public&lt;/url&gt;</span></span>
<span class="line"><span>&lt;/mirror&gt;</span></span></code></pre></div><p>下面这个论点，配置的时候注意一下：<strong>一个仓库只能对应一个镜像，当有多个镜像的mirrorOf指定了同一个仓库，maven只会从第一个匹配的仓库中进行查找</strong></p><h3 id="_3、idea-配置-maven" tabindex="-1">3、IDEA 配置 maven <a class="header-anchor" href="#_3、idea-配置-maven" aria-label="Permalink to &quot;3、IDEA 配置 maven&quot;">​</a></h3><blockquote><p>IDEA 配置 maven</p></blockquote><p>快捷查找框中输入maven，查找与maven相关的设置，然后点击maven</p><p>修改maven的路径（使用本地的Maven），以及修改settings文件的位置和本地仓库的位置</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202311242131645.png" alt="image.png"></p><p>IDEA 有的版本下面有一个 use settings from .mvn/maven.config 选项，进行勾选</p><p>他的意思是： mvn(directory): 位于项目的顶级目录中，文件 maven.config、jvm.config和extensions.xml 包含运行Maven的项目特定配置。这个目录应该是项目的一部分，需要被版本管理工具管理</p><blockquote><p>推荐配置：设置maven在不联网的情况下使用本地插件</p></blockquote><p>一般使用maven为我们提供好的骨架时，是需要联网的，配置这个，可以在没有网路的情况下，我们可以正常创建工程，并从之前已经使用过的工程中找到相应的骨架。（根据骨架创建项目速度会加快）</p><p>输入内容：<code>-DarchetypeCatalog=internal</code></p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/202311242133069.png" alt="image.png"></p><p>输入内容：<code>-DarchetypeCatalog=internal</code></p><h3 id="_4、idea导入项目后maven-常见报错" tabindex="-1">4、IDEA导入项目后maven 常见报错 <a class="header-anchor" href="#_4、idea导入项目后maven-常见报错" aria-label="Permalink to &quot;4、IDEA导入项目后maven 常见报错&quot;">​</a></h3><p>方法一：改一下 maven 配置文件，修改 mirror 仓库位置，重新导入项目，重新加载 maven 依赖</p><p>方法二：IDEA 有的版本下面有一个 use settings from .mvn/maven.config 选项，不进行勾选试一下</p><p>方法三：去一下仓库地址，查看是否是否有该版本依赖，如果没有，改一下版本，或者手动下载，手动导入到本地仓库中</p><blockquote><p>报错1：解决Maven ‘parent.relativePath‘ of POM</p></blockquote><p>错误分析</p><p>子模块的parent写的不是父模块，而是继承了springboot</p><p>解决方法</p><p>在该<code>&lt;parent&gt;</code>标签中加上<code>&lt;relativePath /&gt;</code></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;parent&gt;</span></span>
<span class="line"><span>        &lt;groupId&gt;org.springframework.boot&lt;/groupId&gt;</span></span>
<span class="line"><span>        &lt;artifactId&gt;spring-boot-starter-parent&lt;/artifactId&gt;</span></span>
<span class="line"><span>        &lt;version&gt;2.4.0&lt;/version&gt;</span></span>
<span class="line"><span>        &lt;relativePath   /&gt;</span></span>
<span class="line"><span>    &lt;/parent&gt;</span></span></code></pre></div><blockquote><p>报错2：对于类似于xxx-maven-plugin的插件报红</p></blockquote><p>类似于这样的</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;plugin&gt;</span></span>
<span class="line"><span>	&lt;groupId&gt;org.codehaus.mojo&lt;/groupId&gt;</span></span>
<span class="line"><span>	&lt;artifactId&gt;wagon-maven-plugin&lt;/artifactId&gt;</span></span>
<span class="line"><span>	&lt;version&gt;1.0&lt;/version&gt;</span></span>
<span class="line"><span>&lt;/plugin&gt;</span></span></code></pre></div><p>报红就直接用不了了</p><p>我们可以通过添加依赖的方式解决（原来的插件就是上面的代码<strong>不要删</strong>）:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;dependency&gt;</span></span>
<span class="line"><span>	&lt;groupId&gt;org.codehaus.mojo&lt;/groupId&gt;</span></span>
<span class="line"><span>	&lt;artifactId&gt;wagon-maven-plugin&lt;/artifactId&gt;</span></span>
<span class="line"><span>	&lt;version&gt;1.0&lt;/version&gt;</span></span>
<span class="line"><span>	&lt;type&gt;pom&lt;/type&gt;</span></span>
<span class="line"><span>&lt;/dependency&gt;</span></span></code></pre></div><hr><p>参考</p><ul><li><a href="https://blog.csdn.net/W_317/article/details/126902685" target="_blank" rel="noreferrer">https://blog.csdn.net/W_317/article/details/126902685</a></li><li><a href="https://blog.csdn.net/yang_yzl11/article/details/120764764" target="_blank" rel="noreferrer">https://blog.csdn.net/yang_yzl11/article/details/120764764</a></li><li><a href="https://blog.csdn.net/qq_42057154/article/details/106114515" target="_blank" rel="noreferrer">https://blog.csdn.net/qq_42057154/article/details/106114515</a></li><li><a href="https://www.cnblogs.com/SherlockLynn/p/15079467.html" target="_blank" rel="noreferrer">https://www.cnblogs.com/SherlockLynn/p/15079467.html</a></li><li><a href="https://blog.csdn.net/qq_38217990/article/details/129257106" target="_blank" rel="noreferrer">https://blog.csdn.net/qq_38217990/article/details/129257106</a></li><li><a href="https://zhuanlan.zhihu.com/p/653017610" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/653017610</a></li><li><a href="https://blog.csdn.net/qq_39505065/article/details/111559890" target="_blank" rel="noreferrer">https://blog.csdn.net/qq_39505065/article/details/111559890</a></li><li><a href="https://blog.csdn.net/m0_46682011/article/details/120626933" target="_blank" rel="noreferrer">https://blog.csdn.net/m0_46682011/article/details/120626933</a></li></ul>`,48)])])}const m=n(p,[["render",l]]);export{h as __pageData,m as default};
